 async start():Promise<void>{const directory=this.journal.store.directory('run',true);try{Check.require(!directory.entries().includes('worker.sock'),'WORKER_SOCKET_CONFLICT');const path=directory.path+'/worker.sock';Check.require(Buffer.byteLength(path)<=103,'WORKER_SOCKET_PATH');await new Promise<void>(this.listen.bind(this,path));const stat=lstatSync(path);Check.require(stat.isSocket()&&stat.uid===process.getuid?.(),'WORKER_SOCKET_OWNER');chmodSync(path,0o600);directory.verify();this.active=true;}finally{directory.close();}}
